-- Organization service areas: the geographic regions an organization serves.
-- Matching (Day 3) offers a verified report to organizations whose active
-- capability includes the report's category AND whose active service area
-- covers the report's location.
--
-- Additive only: a new table, two indexes, a foreign key and a CHECK.
-- Requires PostGIS (migration 20261128120000_enable_postgis).

-- CreateTable (generated by `prisma migrate diff`)
CREATE TABLE "OrganizationServiceArea" (
    "id" TEXT NOT NULL,
    "organizationId" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "area" geography(MultiPolygon, 4326) NOT NULL,
    "isActive" BOOLEAN NOT NULL DEFAULT true,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "OrganizationServiceArea_pkey" PRIMARY KEY ("id")
);

-- CreateIndex: GiST lets ST_Covers / ST_DWithin use bounding-box lookups
-- instead of testing every polygon.
CREATE INDEX "OrganizationServiceArea_area_idx" ON "OrganizationServiceArea" USING GIST ("area");

-- CreateIndex: "active areas of organization X"
CREATE INDEX "OrganizationServiceArea_organizationId_isActive_idx" ON "OrganizationServiceArea"("organizationId", "isActive");

-- AddForeignKey
ALTER TABLE "OrganizationServiceArea" ADD CONSTRAINT "OrganizationServiceArea_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- Hand-written (Prisma does not model CHECK constraints, so this causes no drift).
-- The column type already enforces MultiPolygon + SRID 4326. This adds the
-- rules a type cannot express: the shape must be valid (no self-intersection,
-- closed rings, holes inside shells) and non-empty. ST_IsValid is a geometry
-- function, hence the cast; for city-sized areas the planar check matches the
-- geodesic shape closely enough.
ALTER TABLE "OrganizationServiceArea"
  ADD CONSTRAINT "OrganizationServiceArea_area_valid_check"
  CHECK (ST_IsValid("area"::geometry) AND NOT ST_IsEmpty("area"::geometry));

